<?php require __DIR__.'/includes/functions.php';require __DIR__.'/includes/data.php';redirect_if_needed();$slug=$_GET['slug']??'';$cms=published_page($slug);$titles=['safaris'=>'Tanzania Safaris','kilimanjaro'=>'Mount Kilimanjaro','trekking'=>'Trekking in Tanzania','zanzibar'=>'Zanzibar','destinations'=>'Tanzania Destinations','day-trips'=>'Day Trips & Experiences','travel-guide'=>'Tanzania Travel Guide','about'=>'About Tanzania Wildlife Epic','contact'=>'Plan Your Trip','faq'=>'Frequently Asked Questions','migration-safaris'=>'Great Migration Safaris','luxury-safaris'=>'Luxury Tanzania Safaris','family-safaris'=>'Family Tanzania Safaris','privacy'=>'Privacy Policy','terms'=>'Terms & Conditions'];$title=$cms['title']??($titles[$slug]??ucwords(str_replace('-',' ',$slug)));$description=$cms['meta_description']??($title.' with Tanzania Wildlife Epic.');$pageMeta=meta($cms['meta_title']??$title,$description);require __DIR__.'/includes/header.php';?>
<main><section class="inner-hero"><div class="wrap"><nav class="crumb"><a href="/">Home</a> / <?=e($title)?></nav><h1><?=e($title)?></h1><p><?=e($description)?></p></div></section><section class="section wrap"><?php if($cms):?><article class="prose"><?=$cms['body']?></article><?php elseif($slug==='destinations'):?><div class="destination-grid"><?php foreach(destinations() as $d):?><article id="<?=e($d['slug'])?>"><h2><?=e($d['name'])?></h2><p><?=e($d['text'])?></p><a href="/destination/<?=e($d['slug'])?>">Explore destination →</a></article><?php endforeach;?></div><?php elseif($slug==='contact'):?><div class="contact-grid"><div><h2>Tell us what you want to do</h2><p>Send your travel dates, group size, preferred trip length and whether you want safari, trekking, Zanzibar or a combination.</p><p><strong>Phone / WhatsApp:</strong> <?=e(site_config()['site']['phone'])?><br><strong>Email:</strong> <?=e(site_config()['site']['email'])?></p></div><form class="contact-form" action="/enquiry.php" method="post"><input name="name" placeholder="Your name" required><input type="email" name="email" placeholder="Email" required><input name="phone" placeholder="Phone / WhatsApp"><input name="trip" value="<?=e($_GET['trip']??'')?>" placeholder="Trip or interest"><textarea name="message" placeholder="Dates, group size and what you would like to do" required></textarea><button class="btn gold">Send Enquiry</button></form></div><?php elseif(in_array($slug,['safaris','kilimanjaro','trekking','zanzibar','day-trips','migration-safaris','luxury-safaris','family-safaris'])):?><?php $maxDays=(int)($_GET['max_days']??0);$location=trim($_GET['location']??'');$tourType=trim($_GET['tour_type']??'');$filter=array_filter(all_public_packages(),function($p)use($slug,$maxDays,$location,$tourType){$ok=true;if($slug==='safaris'||str_contains($slug,'safaris'))$ok=($p['category']??'')==='Safari';elseif($slug==='kilimanjaro')$ok=($p['category']??'')==='Kilimanjaro';elseif($slug==='trekking')$ok=in_array(($p['category']??''),['Kilimanjaro','Trekking']);elseif($slug==='zanzibar')$ok=($p['category']??'')==='Zanzibar';elseif($slug==='day-trips')$ok=($p['category']??'')==='Day Trips';if($maxDays&&($p['days']??99)>$maxDays)$ok=false;if($location&&stripos($p['location']??'',$location)===false)$ok=false;if($tourType&&stripos($p['type']??'',$tourType)===false)$ok=false;return $ok;});?><form class="filter-bar" method="get"><label>Maximum duration<select name="max_days"><option value="">Any</option><?php foreach([1,4,5,7,10,15] as $n):?><option value="<?=$n?>" <?=$maxDays===$n?'selected':''?>>Up to <?=$n?> days</option><?php endforeach;?></select></label><label>Location<input name="location" value="<?=e($location)?>" placeholder="Serengeti, Kilimanjaro..."></label><label>Travel style<input name="tour_type" value="<?=e($tourType)?>" placeholder="Private, Group, Trekking..."></label><button class="btn dark">Filter Trips</button></form><p><strong><?=count($filter)?></strong> matching trip<?=count($filter)===1?'':'s'?></p><div class="cards"><?php foreach($filter as $p):?><article class="trip-card"><div class="trip-body"><span><?=e($p['days'])?> day<?= $p['days']==1?'':'s' ?> · <?=e($p['category']??'')?></span><h3><?=e($p['title'])?></h3><p><?=e($p['summary'])?></p><p><small><?=e($p['location']??'')?> · <?=e($p['type']??'')?></small></p><a href="/package/<?=e($p['slug'])?>">View itinerary →</a></div></article><?php endforeach;?></div><?php elseif($slug==='travel-guide'):?><?php $articles=published_articles();if($articles):?><div class="cards"><?php foreach($articles as $a):?><article class="trip-card"><div class="trip-body"><span>Travel Guide</span><h3><?=e($a['title'])?></h3><p><?=e($a['excerpt'])?></p><a href="/article/<?=e($a['slug'])?>">Read article →</a></div></article><?php endforeach;?></div><?php else:?><div class="prose"><h2>Tanzania travel planning notes</h2><p>Travel guide articles published in the CMS will appear here.</p></div><?php endif;?><?php elseif($slug==='faq'):?><?php $faqRows=[];$pdo=db();if($pdo){try{$faqRows=$pdo->query("SELECT * FROM faqs WHERE status='published' ORDER BY category,sort_order,id")->fetchAll();}catch(Throwable $e){}}?><div class="faq"><?php if($faqRows):foreach($faqRows as $i=>$f):?><details <?=$i===0?'open':''?>><summary><?=e($f['question'])?></summary><p><?=nl2br(e($f['answer']))?></p></details><?php endforeach;else:?><details open><summary>Can I combine safari, Kilimanjaro and Zanzibar?</summary><p>Yes. Tanzania Wildlife Epic can structure a combined itinerary around your available days and preferred travel style.</p></details><details><summary>Are wildlife sightings guaranteed?</summary><p>No. Wildlife is wild and natural sightings cannot be guaranteed.</p></details><details><summary>Why are some prices not shown?</summary><p>Prices are shown only when verified. Otherwise the site uses Request a Quote.</p></details><?php endif;?></div><?php else:?><div class="prose"><h2>Travel planning built around Tanzania</h2><p>Tanzania Wildlife Epic focuses on Tanzania itineraries spanning wildlife safaris, mountain trekking, Zanzibar and selected day experiences. This rebuild keeps business information conservative and avoids unverified claims.</p><p>Use the enquiry form to request an itinerary built around your dates, trip length and preferred travel style.</p><a class="btn gold" href="/contact">Plan Your Trip</a></div><?php endif;?></section></main><?php require __DIR__.'/includes/footer.php';?>
